1276		priv->dmaops->disable_rxirq(priv);
1277		priv->dmaops->disable_txirq(priv);
1278		spin_unlock_irqrestore(&priv->rxdma_irq_lock, flags);
1279	
1280		/* Free the IRQ lines */
